CREATE TABLE public.seo_review_settings (id boolean PRIMARY KEY DEFAULT true CHECK(id), seo_admin_id uuid REFERENCES public.admin_users(id) ON DELETE SET NULL, site_url text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.seo_review_settings TO authenticated; GRANT ALL ON public.seo_review_settings TO service_role;
ALTER TABLE public.seo_review_settings ENABLE ROW LEVEL SECURITY;
INSERT INTO public.seo_review_settings(id) VALUES(true);
CREATE OR REPLACE FUNCTION public.can_review_seo(p_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.admin_users a WHERE a.user_id=p_user AND a.is_active=true AND a.archived_at IS NULL AND (a.role='super_admin' OR a.id=(SELECT seo_admin_id FROM public.seo_review_settings WHERE id=true))); $$;
REVOKE ALL ON FUNCTION public.can_review_seo(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.can_review_seo(uuid) TO authenticated,service_role;
CREATE POLICY seo_settings_read ON public.seo_review_settings FOR SELECT TO authenticated USING(public.can_review_seo((SELECT auth.uid())));
CREATE TABLE public.seo_review_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), audit_week date NOT NULL UNIQUE, status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','running','complete','partial','failed')), report jsonb NOT NULL DEFAULT '{}'::jsonb, lease_until timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.seo_review_runs TO authenticated; GRANT ALL ON public.seo_review_runs TO service_role;
ALTER TABLE public.seo_review_runs ENABLE ROW LEVEL SECURITY;
CREATE POLICY seo_runs_read ON public.seo_review_runs FOR SELECT TO authenticated USING(public.can_review_seo((SELECT auth.uid())));
CREATE TABLE public.seo_review_proposals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid NOT NULL REFERENCES public.seo_review_runs(id) ON DELETE CASCADE, category text NOT NULL, page_url text NOT NULL, title text NOT NULL, evidence text NOT NULL, proposed_change text NOT NULL, verification text NOT NULL, priority text NOT NULL, decision text NOT NULL DEFAULT 'pending' CHECK(decision IN ('pending','approved','rejected')), reviewed_by uuid, reviewed_at timestamptz, review_note text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.seo_review_proposals TO authenticated; GRANT ALL ON public.seo_review_proposals TO service_role;
ALTER TABLE public.seo_review_proposals ENABLE ROW LEVEL SECURITY;
CREATE POLICY seo_proposals_read ON public.seo_review_proposals FOR SELECT TO authenticated USING(public.can_review_seo((SELECT auth.uid())));
CREATE TABLE public.seo_review_notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid NOT NULL REFERENCES public.seo_review_runs(id) ON DELETE CASCADE, user_id uuid NOT NULL, title text NOT NULL, message text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(run_id,user_id));
GRANT SELECT ON public.seo_review_notifications TO authenticated; GRANT ALL ON public.seo_review_notifications TO service_role;
ALTER TABLE public.seo_review_notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY seo_notifications_read ON public.seo_review_notifications FOR SELECT TO authenticated USING(user_id=(SELECT auth.uid()) AND public.can_review_seo((SELECT auth.uid())));
CREATE OR REPLACE FUNCTION public.seo_review_touch() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END; $$;
CREATE TRIGGER seo_settings_touch BEFORE UPDATE ON public.seo_review_settings FOR EACH ROW EXECUTE FUNCTION public.seo_review_touch();
CREATE TRIGGER seo_runs_touch BEFORE UPDATE ON public.seo_review_runs FOR EACH ROW EXECUTE FUNCTION public.seo_review_touch();
CREATE TRIGGER seo_proposals_touch BEFORE UPDATE ON public.seo_review_proposals FOR EACH ROW EXECUTE FUNCTION public.seo_review_touch();
CREATE TRIGGER seo_notifications_touch BEFORE UPDATE ON public.seo_review_notifications FOR EACH ROW EXECUTE FUNCTION public.seo_review_touch();
CREATE OR REPLACE FUNCTION public.seo_review_configuration() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE caller public.admin_users; BEGIN SELECT * INTO caller FROM public.admin_users WHERE user_id=(SELECT auth.uid()) AND is_active=true AND archived_at IS NULL; IF NOT public.can_review_seo((SELECT auth.uid())) THEN RAISE EXCEPTION 'SEO review access required' USING ERRCODE='42501'; END IF; RETURN jsonb_build_object('is_super_admin',caller.role='super_admin','settings',(SELECT to_jsonb(s) FROM public.seo_review_settings s WHERE id=true),'staff',CASE WHEN caller.role='super_admin' THEN (SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'name',coalesce(nullif(trim(concat_ws(' ',first_name,last_name)),''),email),'email',email) ORDER BY email),'[]'::jsonb) FROM public.admin_users WHERE is_active=true AND archived_at IS NULL AND user_id IS NOT NULL) ELSE '[]'::jsonb END); END; $$;
CREATE OR REPLACE FUNCTION public.configure_seo_reviews(p_seo_admin_id uuid, p_site_url text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.admin_users WHERE user_id=(SELECT auth.uid()) AND is_active=true AND archived_at IS NULL AND role='super_admin') THEN RAISE EXCEPTION 'Super-admin approval required' USING ERRCODE='42501'; END IF; IF p_seo_admin_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.admin_users WHERE id=p_seo_admin_id AND is_active=true AND archived_at IS NULL AND user_id IS NOT NULL) THEN RAISE EXCEPTION 'Select an active staff account'; END IF; IF p_site_url IS NOT NULL AND (length(p_site_url)>300 OR p_site_url NOT LIKE 'https://%' OR p_site_url NOT LIKE '%buyawarranty.co.uk%') THEN RAISE EXCEPTION 'Invalid Search Console property'; END IF; UPDATE public.seo_review_settings SET seo_admin_id=p_seo_admin_id,site_url=p_site_url WHERE id=true; END; $$;
CREATE OR REPLACE FUNCTION public.decide_seo_proposal(p_id uuid,p_decision text,p_note text DEFAULT '') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.admin_users WHERE user_id=(SELECT auth.uid()) AND is_active=true AND archived_at IS NULL AND role='super_admin') THEN RAISE EXCEPTION 'Only super admins can authorise changes' USING ERRCODE='42501'; END IF; IF p_decision NOT IN ('approved','rejected') OR length(coalesce(p_note,''))>2000 THEN RAISE EXCEPTION 'Invalid review decision'; END IF; UPDATE public.seo_review_proposals SET decision=p_decision,reviewed_by=(SELECT auth.uid()),reviewed_at=now(),review_note=p_note WHERE id=p_id AND decision='pending'; IF NOT FOUND THEN RAISE EXCEPTION 'Proposal already reviewed or unavailable'; END IF; END; $$;
CREATE OR REPLACE FUNCTION public.read_seo_notifications(p_id uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.can_review_seo((SELECT auth.uid())) THEN RAISE EXCEPTION 'SEO access required' USING ERRCODE='42501'; END IF; UPDATE public.seo_review_notifications SET read_at=now() WHERE user_id=(SELECT auth.uid()) AND read_at IS NULL AND (p_id IS NULL OR id=p_id); END; $$;
CREATE OR REPLACE FUNCTION public.claim_weekly_seo_run() RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE claimed uuid; BEGIN UPDATE public.seo_review_runs SET status='running',lease_until=now()+interval '10 minutes' WHERE id=(SELECT id FROM public.seo_review_runs WHERE status='queued' AND audit_week<=current_date ORDER BY audit_week LIMIT 1 FOR UPDATE SKIP LOCKED) RETURNING id INTO claimed; RETURN claimed; END; $$;
REVOKE ALL ON FUNCTION public.claim_weekly_seo_run() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.claim_weekly_seo_run() TO service_role;
CREATE OR REPLACE FUNCTION public.notify_seo_review() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status IN ('complete','partial','failed') AND OLD.status IS DISTINCT FROM NEW.status THEN INSERT INTO public.seo_review_notifications(run_id,user_id,title,message) SELECT NEW.id,a.user_id,CASE WHEN NEW.status='failed' THEN 'Weekly SEO review needs attention' ELSE 'Weekly SEO review ready' END,CASE WHEN NEW.status='complete' THEN 'Review the evidence and proposed changes in SEO Audit. Nothing has been changed.' ELSE 'Some checks could not complete. Review the coverage gaps in SEO Audit. Nothing has been changed.' END FROM public.admin_users a WHERE a.is_active=true AND a.archived_at IS NULL AND a.user_id IS NOT NULL AND (a.role='super_admin' OR a.id=(SELECT seo_admin_id FROM public.seo_review_settings WHERE id=true)) ON CONFLICT(run_id,user_id) DO NOTHING; END IF; RETURN NEW; END; $$;
CREATE TRIGGER seo_review_notify AFTER UPDATE OF status ON public.seo_review_runs FOR EACH ROW EXECUTE FUNCTION public.notify_seo_review();
REVOKE ALL ON FUNCTION public.seo_review_configuration(),public.configure_seo_reviews(uuid,text),public.decide_seo_proposal(uuid,text,text),public.read_seo_notifications(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.seo_review_configuration(),public.configure_seo_reviews(uuid,text),public.decide_seo_proposal(uuid,text,text),public.read_seo_notifications(uuid) TO authenticated;
REVOKE ALL ON FUNCTION public.notify_seo_review(),public.seo_review_touch() FROM PUBLIC,anon,authenticated;
CREATE INDEX seo_proposals_run_idx ON public.seo_review_proposals(run_id);
CREATE INDEX seo_notifications_user_idx ON public.seo_review_notifications(user_id,created_at DESC);